> **Rappel -** Ce TD manipule beaucoup de tableaux NumPy multi-dimensionnels (remettre en forme des images sous forme de listes de pixels, appliquer une pondération à toutes les colonnes d'une matrice, recalculer des distances...). Si ces manipulations ne sont pas encore des automatismes pour vous, nous vous conseillons fortement de consulter :
> - le [guide de démarrage NumPy](https://numpy.org/doc/stable/user/quickstart.html) (formes, `reshape`, indexation...) ;
> - la page officielle sur le [*broadcasting*](https://numpy.org/doc/stable/user/basics.broadcasting.html), qui explique avec des exemples comment NumPy applique automatiquement une opération (par exemple une multiplication) à toutes les lignes ou colonnes d'une matrice — exactement ce qu'on utilisera pour pondérer nos histogrammes de couleurs.

# deux paires de couleurs, choisies pour avoir exactement la même distance euclidienne en RGB
paire_A = (np.array([35, 239, 234]), np.array([5, 239, 236]))   # deux cyans très proches
paire_B = (np.array([3, 12, 70]), np.array([5, 36, 52]))        # deux bleus nuit

def distance_rgb(c1, c2):
    return np.linalg.norm(c1.astype(float) - c2.astype(float))

def distance_lab(c1, c2):
    lab1 = rgb2lab(c1.reshape(1, 1, 3) / 255.0).reshape(3)
    lab2 = rgb2lab(c2.reshape(1, 1, 3) / 255.0).reshape(3)
    return np.linalg.norm(lab1 - lab2)

fig, axes = plt.subplots(2, 2, figsize=(5, 5))
for row, (c1, c2, nom) in enumerate([(*paire_A, "Paire A"), (*paire_B, "Paire B")]):
    for col, c in enumerate([c1, c2]):
        axes[row, col].imshow(np.ones((10, 10, 3)) * c / 255.0)
        axes[row, col].axis("off")
    d_rgb, d_lab = distance_rgb(c1, c2), distance_lab(c1, c2)
    axes[row, 0].set_title(f"{nom} : d_RGB={d_rgb:.1f}  d_LAB={d_lab:.1f}", fontsize=9, loc="left")
plt.tight_layout()
plt.show()

